const selection=[['Hip-hop / Soul','A different kind of rotation',-97,-642,-81,-537],['N.E.R.D','Alternative / Hip-hop',-293,-642,-245,-537],['Queens of the Stone Age','Rock / Alternative',-489,-642,-409,-537],['On the frequency','Discover something new',-676,-642,-565,-537],['Jamiroquai','Funk / Acid jazz',-872,-642,-729,-537],['Culture on repeat','Independent / Eclectic',-1080,-642,-903,-537]];
const group=document.createElement('div');group.className='album-group';
selection.forEach(([title,subtitle,x,y,mx,my])=>{const item=document.createElement('div');item.className='album';item.innerHTML=`<div class="sleeve"><div class="cover" role="img" aria-label="Album artwork from the supplied visual reference" style="background-position:${x}px ${y}px;--mobile-pos:${mx}px ${my}px"></div></div><p>${title}</p><small>${subtitle}</small>`;group.append(item)});
const track=document.querySelector('#albums');track.append(group);const duplicate=group.cloneNode(true);duplicate.setAttribute('aria-hidden','true');track.append(duplicate);
const pause=document.querySelector('#pause');pause.addEventListener('click',()=>{const paused=track.classList.toggle('paused');pause.setAttribute('aria-pressed',String(paused));pause.querySelector('svg path').setAttribute('d',paused?'M6 3 21 12 6 21Z':'M6 3h4v18H6ZM14 3h4v18h-4Z');pause.lastChild.textContent=paused?' RESUME':' PAUSE'});
const menu=document.querySelector('.menu'),nav=document.querySelector('#navigation');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menu.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.textContent='☰'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open'))menu.click()});
const links=[...nav.querySelectorAll('a')];const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){links.forEach(a=>{const active=a.hash==='#'+entry.target.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}})},{rootMargin:'-20% 0px -55% 0px'});document.querySelectorAll('section[id]').forEach(section=>observer.observe(section));
const form=document.querySelector('#proposal'),success=document.querySelector('#success');form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;form.hidden=true;success.hidden=false;success.focus({preventScroll:true})});document.querySelector('#reset').addEventListener('click',()=>{form.reset();success.hidden=true;form.hidden=false;form.elements.name.focus({preventScroll:true})});
